 if(state.result&&$('showResults').checked)for(const e of state.result.elements||[]){if(!visible(e)||!e.line)continue;ctx.strokeStyle=colour(e.value);ctx.lineWidth=4;line(e.line[0],e.line[1]);const a=project(e.line[0]),b=project(e.line[1]),dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy)||1,n=[-dy/len*5,dx/len*5],p=new Path2D();p.moveTo(a[0]+n[0],a[1]+n[1]);p.lineTo(b[0]+n[0],b[1]+n[1]);p.lineTo(b[0]-n[0],b[1]-n[1]);p.lineTo(a[0]-n[0],a[1]-n[1]);p.closePath();state.hits.push({element:e,path:p})}
