 if(state.result?.route){ctx.strokeStyle='#ec6363';ctx.lineWidth=4;const levels=state.model.storeys;const level=p=>[...levels].sort((a,b)=>Math.abs(a.elevation-p[2])-Math.abs(b.elevation-p[2]))[0]?.id;for(let i=1;i<state.result.route.points.length;i++){const a=state.result.route.points[i-1],b=state.result.route.points[i];if(!$('isolate').checked||(level(a)===$('boundary').value&&level(b)===$('boundary').value))line(a,b);}}
 if(state.selected?.isovist){ctx.fillStyle='#3766ed33';ctx.strokeStyle='#3766ed';ctx.lineWidth=1.5;const p=pathFor({outer:state.selected.isovist,holes:state.selected.isovist_holes});ctx.fill(p,'evenodd');ctx.stroke(p)}
