 $('scaleLabel').textContent=(100/state.view.scale).toFixed(1)+' m';$('viewportBadge').textContent=`${$('isolate').checked?$('boundary').selectedOptions[0]?.textContent:'All storeys'} · ${state.view.pitch>1.55?'TOP':'3D'} · PERSPECTIVE`;frameCamera=null;
