function fit(){if(!state.model)return;const points=[...modelSurfaces(),...connectorSurfaces()].flatMap(s=>s.outer);if(!points.length)return;const mins=[Infinity,Infinity,Infinity],maxs=[-Infinity,-Infinity,-Infinity];for(const p of points)for(let k=0;k<3;k++){mins[k]=Math.min(mins[k],p[k]||0);maxs[k]=Math.max(maxs[k],p[k]||0)}state.view.centre=mins.map((v,k)=>(v+maxs[k])/2);state.view.pan=[0,0];state.view.radius=Math.max(.1,Math.hypot(...maxs.map((v,k)=>(v-mins[k])/2)));const c=camera(),aspect=Math.max(.1,state.width/Math.max(1,state.height)),angle=Math.atan(Math.tan(25*Math.PI/180)*Math.min(1,aspect)),distance=state.view.radius/Math.sin(angle)*1.15;state.view.scale=c.f/distance;draw()}
