function updateContext(){$('clearanceControl').hidden=state.tab==='syntax'&&!['grid_shell','visibility'].includes($('graphMode').value);document.body.dataset.mode=state.tab;$('isovistOptions').hidden=state.tab!=='isovist';$('graphControl').hidden=state.tab!=='syntax';$('pathControls').hidden=state.tab!=='path';$('scope').parentElement.querySelector('label[for=scope]').hidden=state.tab==='isovist';$('scope').hidden=state.tab==='isovist';$('weight').parentElement.hidden=state.tab!=='syntax';$('metric').hidden=state.tab==='path';$('normalize').parentElement.hidden=state.tab!=='syntax';advanced.hidden=state.tab!=='syntax';$('run').hidden=state.tab==='isovist'&&$('isoMode').value==='point';$('canvasHint').textContent=state.tab==='path'?'Click start and destination · Drag to rotate · Right-drag to pan':state.tab==='isovist'&&$('isoMode').value==='point'?'Click an eye-level face · Drag to rotate · Right-drag to pan':'Drag to rotate · Right-drag to pan · Scroll to zoom · Hover to inspect';$('showContext').parentElement.hidden=!state.model?.context?.length;$('contextOpacity').hidden=!state.model?.context?.length;$('contextOpacity').previousElementSibling.hidden=!state.model?.context?.length;}
function request(){const number=id=>$(id).value?+$(id).value:null;return {model:state.model,boundary:state.model.faces[0]?.id||0,kind:state.tab,metric:$('metric').value,spacing:+$('spacing').value,clearance:state.tab==='syntax'&&!['grid_shell','visibility'].includes($('graphMode').value)?0:+$('clearance').value,graph_mode:$('graphMode').value,storey:state.tab==='isovist'||$('scope').value==='storey'?$('boundary').value:null,weight:$('weight').value,normalize:$('normalize').checked,fov:+$('fov').value,direction:+$('direction').value,point:state.tab==='isovist'&&$('isoMode').value==='point'?state.point:null,radius:number('radius'),radius_type:$('radiusType').value,algorithm:$('algorithm').value,weighting:$('weighting').value,step:+$('steps').value,tulip_bins:+$('tulipBins').value,min_overlap:+$('minOverlap').value,isovist_radius:number('isovistRadius'),compute_overlap:$('computeOverlap').checked,axial_reduce:$('axialReduce').checked,axial_sampling_distance:number('axialSampling'),path_graph:$('pathGraph').value,path_start:state.start,path_end:state.end,straighten:$('straightenPath').checked}}
async function run(){if(state.busy)return;if(!state.connected){$('connectionDialog').showModal();return}if(state.tab==='path'&&(!state.start||!state.end)){toast('Click a start and a destination on floor surfaces.');return}if(state.tab==='isovist'&&$('isoMode').value==='point'&&!state.point){toast('Choose a viewpoint on an eye-level face.');return}busy(true,'Computing your building analysis…');try{const r=await api('/api/analyze',{method:'POST',body:JSON.stringify(request())});setResult(r);$('statusText').textContent=`${r.name} · ${r.elapsed.toFixed(2)} s`;}catch(e){if(state.tab==='path'){clearResults();draw()}toast(e.message);$('statusText').textContent=e.message}finally{busy(false)}}
function setResult(r){state.result=r;state.selected=null;const vals=r.elements.map(e=>e.value).filter(v=>v!=null&&Number.isFinite(v));$('rangeMin').value=vals.length?Math.min(...vals):0;$('rangeMax').value=vals.length?Math.max(...vals):1;$('minimum').textContent=vals.length?Math.min(...vals).toFixed(3):'—';$('maximum').textContent=vals.length?Math.max(...vals).toFixed(3):'—';$('average').textContent=vals.length?(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(3):'—';$('averageCaption').textContent=r.name;$('count').textContent=r.elements.length;$('edges').textContent=r.graph.edges.length;$('viewName').textContent=r.name;$('canvasTitle').textContent=r.name.toUpperCase();$('legendTitle').textContent=r.name;$('legendUnit').textContent=r.unit;$('overviewSection').hidden=!vals.length;$('displaySection').hidden=!vals.length;document.querySelector('.legend').hidden=!vals.length;$('pathLength').textContent=r.route?r.route.length.toFixed(2)+' m':'—';$('histogram').replaceChildren();if(vals.length){const min=Math.min(...vals),max=Math.max(...vals),bins=Array(16).fill(0);vals.forEach(v=>bins[Math.min(15,Math.floor((v-min)/(max-min||1)*16))]++);for(let i=0;i<16;i++){const bar=document.createElement('div');bar.style.height=(bins[i]/Math.max(...bins)*100)+'%';bar.style.background=colour(min+(max-min)*i/15);$('histogram').append(bar)}}updateColours()}
function updateColours(){const arr=palettes[$('palette').value];const gradient=`linear-gradient(90deg,${($('reverse').checked?[...arr].reverse():arr).join(',')})`;$('palettePreview').style.background=gradient;$('legendGradient').style.background=gradient;$('legendTicks').replaceChildren(...[0,.25,.5,.75,1].map(t=>{const e=document.createElement('span');e.textContent=(+$('rangeMin').value+(+$('rangeMax').value-+$('rangeMin').value)*t).toFixed(2);return e}));$('opacityValue').textContent=$('opacity').value+'%';draw()}
function hover(x,y,pin=false){const hit=hitAt(x,y,h=>h.element);if(!hit){$('tooltip').hidden=true;return}const e=hit.element;state.selected=e;const level=state.model.storeys.find(s=>s.id===e.storey)?.name||'';$('inspector').replaceChildren();for(const text of [level,state.result.name+': '+(e.value==null?'Unavailable':e.value.toFixed(4)),`X ${e.point[0].toFixed(2)} · Y ${e.point[1].toFixed(2)} · Z ${e.point[2].toFixed(2)} m`,e.kind||'isovist',...Object.entries(e.metrics||{}).filter(([,v])=>typeof v==='number').map(([k,v])=>`${k}: ${v.toFixed(4)}`)]){const p=document.createElement('p');p.textContent=text;$('inspector').append(p)}$('tooltip').textContent=(e.value==null?'Unavailable':e.value.toFixed(4))+' · '+level;$('tooltip').style.left=Math.min(x+14,state.width-200)+'px';$('tooltip').style.top=Math.max(5,y-40)+'px';$('tooltip').hidden=pin;draw()}
let drag=null;canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(state.busy)return;canvas.setPointerCapture(e.pointerId);drag={x:e.offsetX,y:e.offsetY,lastX:e.offsetX,lastY:e.offsetY,button:e.button,pan:e.shiftKey||e.button===2,moved:false}});canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.offsetX-drag.lastX,dy=e.offsetY-drag.lastY;if(Math.hypot(e.offsetX-drag.x,e.offsetY-drag.y)>4)drag.moved=true;if(drag.moved){if(drag.pan){state.view.pan[0]+=dx;state.view.pan[1]+=dy}else{state.view.yaw-=dx*.008;state.view.pitch=Math.max(-Math.PI/2+.01,Math.min(Math.PI/2,state.view.pitch+dy*.008))}draw()}drag.lastX=e.offsetX;drag.lastY=e.offsetY}else hover(e.offsetX,e.offsetY)});
canvas.addEventListener('pointerup',e=>{const d=drag;drag=null;if(!d||d.moved||d.button!==0)return;const x=e.offsetX,y=e.offsetY;const hit=hitAt(x,y,h=>h.pick);if(!hit){hover(x,y,true);return}const point=unprojectOnPlane(x,y,hit.s);if(!point)return;if(state.tab==='path'){if(state.pathPick==='start'){state.start=point;state.end=null;state.pathPick='end'}else{state.end=point;state.pathPick='start';run()}pickButtons();draw()}else if(state.tab==='isovist'&&$('isoMode').value==='point'){state.point=point;run()}else hover(x,y,true)});canvas.addEventListener('wheel',e=>{e.preventDefault();state.view.scale=Math.max(.02,Math.min(5000,state.view.scale*Math.exp(-e.deltaY*.001)));draw()},{passive:false});
function pickButtons(){$('pickStart').classList.toggle('active',state.pathPick==='start');$('pickEnd').classList.toggle('active',state.pathPick==='end')}
$('pickStart').onclick=()=>{state.pathPick='start';pickButtons()};$('pickEnd').onclick=()=>{state.pathPick='end';pickButtons()};
$('run').onclick=run;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(state.busy)return;state.tab=b.dataset.tab;clearResults();state.selected=null;state.point=null;document.querySelectorAll('[data-tab]').forEach(btn=>btn.classList.toggle('active',btn===b));setMetrics();updateContext();document.querySelector('.legend').hidden=true;$('pathLength').textContent='—';draw()});
$('boundary').onchange=()=>{state.point=null;state.selected=null;if(state.tab==='isovist'||$('scope').value==='storey')clearResults();draw()};$('scope').onchange=()=>{clearResults();draw()};$('isolate').onchange=()=>{draw()};$('isoMode').onchange=()=>{clearResults();state.point=null;updateContext();draw()};
for(const id of ['showResults','showPlan','showGraph','showGrid','showContext'])$(id).onchange=draw;for(const id of ['palette','reverse','rangeMin','rangeMax','opacity'])$(id).oninput=updateColours;$('contextOpacity').oninput=()=>{$('contextOpacityValue').textContent=$('contextOpacity').value+'%';draw()};$('resetRange').onclick=()=>{if(state.result)setResult(state.result)};$('zoomIn').onclick=()=>{state.view.scale*=1.25;draw()};$('zoomOut').onclick=()=>{state.view.scale/=1.25;draw()};$('fit').onclick=fit;$('topView').onclick=()=>{state.view.yaw=0;state.view.pitch=Math.PI/2;fit()};$('orbitView').onclick=()=>{state.view.yaw=-.65;state.view.pitch=.75;fit()};
$('import').onclick=$('dropzone').onclick=()=>$('file').click();$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;if(!state.connected){$('connectionDialog').showModal();return}busy(true,'Importing your model…');try{const form=new FormData();form.append('file',f);loadModel(await api('/api/import',{method:'POST',body:form}))}catch(e){toast(e.message)}finally{busy(false);$('file').value=''}};
$('connect').onclick=()=>{$('endpoint').value=state.endpoint;$('connectionDialog').showModal()};$('saveConnection').onclick=async()=>{state.endpoint=$('endpoint').value;state.token=$('apiKey').value;try{const h=await api('/api/health');if(!h.capabilities?.building_3d)throw Error('Connect the TopologicLab service.');setConnected(true);$('connectionDialog').close();$('engineVersion').textContent=`TopologicPy ${h.version} · TopologicLab`;}catch(e){$('connectionError').textContent=e.message}};$('disconnect').onclick=()=>{setConnected(false);$('connectionDialog').close()};$('guide').onclick=()=>$('guideDialog').showModal();$('example').onclick=()=>loadModel(defaultPlan);
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('export').onclick=()=>{if(!state.result){toast('Run an analysis first.');return}$('exportDialog').showModal()};const ex=document.createElement('dialog');ex.id='exportDialog';ex.innerHTML='<form method="dialog"><button class="dialog-close">×</button></form><h2>Export your building analysis</h2><div class="export-options"><button class="button primary" id="exportJSON">Full project · JSON</button><button class="button" id="exportCSV">Results · CSV</button><button class="button" id="exportPNG">Viewport · PNG</button></div>';document.body.append(ex);
$('exportJSON').onclick=()=>download(JSON.stringify({model:state.model,result:state.result,display:{palette:$('palette').value,min:+$('rangeMin').value,max:+$('rangeMax').value,view:state.view}},null,2),'topologiclab.json','application/json');$('exportCSV').onclick=()=>{const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const rows=[['id','node','storey','kind','x','y','z','value','polygon','holes','metrics'],...state.result.elements.map(e=>[e.id,e.node,e.storey,e.kind,...e.point,e.value,JSON.stringify(e.polygon),JSON.stringify(e.holes),JSON.stringify(e.metrics)])];if(state.result.route){rows.push(['route_point','','','','x','y','z']);state.result.route.points.forEach((p,i)=>rows.push([i,'','','',...p]))}download(rows.map(r=>r.map(quote).join(',')).join('\r\n'),'topologiclab.csv','text/csv')};$('exportPNG').onclick=()=>{const output=document.createElement('canvas');output.width=canvas.width;output.height=canvas.height;const painter=output.getContext('2d');painter.drawImage(faceCanvas,0,0);painter.drawImage(canvas,0,0);output.toBlob(blob=>{const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='topologiclab.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})};
new ResizeObserver(resize).observe($('canvasWrap'));setMetrics();loadModel(defaultPlan);resize();fit();updateColours();document.querySelector('.legend').hidden=true;
api('/api/health').then(h=>{if(h.capabilities?.building_3d){setConnected(true);$('engineVersion').textContent=`TopologicPy ${h.version} · TopologicLab`}}).catch(()=>{});

$('demo3d').onclick=async()=>{if(!state.connected){$('connectionDialog').showModal();return}busy(true,'Loading the example IFC building…');try{loadModel(await api('/api/example'));$('spacing').value='1.5';}catch(e){toast(e.message)}finally{busy(false)}};

function clearResults(){state.result=null;state.selected=null;$('tooltip').hidden=true;['average','minimum','maximum','count','edges'].forEach(id=>$(id).textContent='—');$('histogram').replaceChildren();$('displaySection').hidden=true;$('overviewSection').hidden=true;document.querySelector('.legend').hidden=true;$('pathLength').textContent='—';$('viewName').textContent=state.tab==='path'?'Shortest path':state.tab==='isovist'?'Isovist':'Building';$('canvasTitle').textContent=$('viewName').textContent.toUpperCase();const text=document.createElement('p');text.textContent='Hover over a result to inspect its value.';$('inspector').replaceChildren(text);}
for(const id of ['fov','direction','metric'])$(id).addEventListener('change',()=>{if(state.tab==='isovist'&&$('isoMode').value==='point'&&state.point&&!state.busy)run()});

for(const id of ['spacing','clearance','graphMode','pathGraph'])$(id).addEventListener('change',()=>{clearResults();updateContext();draw()});
